# Now let's classify all keyword-matched dialogs for each company
# Process in batches to manage the workload

company_booking_counts = {}

for company in companies_list:
    if company not in potential_booking_dialogs:
        company_booking_counts[company] = 0
        continue

    dialogs = potential_booking_dialogs[company]
    prompts = [create_classification_prompt(d['dialog']) for d in dialogs]

    # Process in batches of 50
    batch_size = 50
    yes_count = 0

    for i in range(0, len(prompts), batch_size):
        batch = prompts[i:i+batch_size]
        results = llm_query_batched(batch)
        for r in results:
            if r.strip().upper() == 'YES':
                yes_count += 1

    company_booking_counts[company] = yes_count
    print(f"{company}: {yes_count} flight booking complaints out of {len(dialogs)} keyword-matched dialogs")

print(f"\nFinal counts:")
for company, count in sorted(company_booking_counts.items(), key=lambda x: -x[1]):
    print(f"  {company}: {count}")
